import os, tarfile

def restaurar_viagens(pacote, destino):
    base = os.path.realpath(destino)
    with tarfile.open(pacote) as tf:
        for m in tf.getmembers():
            alvo = os.path.realpath(os.path.join(base, m.name))
            if os.path.commonpath([base, alvo]) != base or m.issym() or m.islnk():
                raise ValueError(f"entrada insegura: {m.name}")
            tf.extract(m, base)

